import {analyze,number,validBarcode,fromOFF,DEMOS,METRICS,RULE_VERSION} from './analysis.js';
const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let saved=read('nl-scans',[]),prefs=read('nl-prefs',{allergies:[]});if(!Array.isArray(saved))saved=[];if(!Array.isArray(prefs?.allergies))prefs={allergies:[]};
let view='home',tab='barcode',current=null,basis='100',draft=null,stream=null,timer,ocrBusy=false,busy=false,lastLookup=0;const cache=new Map();
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),5000)}
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Storage is unavailable. Changes only last for this visit.');return false}}
const heading=(t,s,e='')=>`<div class="page-heading"><div><h1>${t}</h1><p>${s}</p></div>${e}</div>`;
const sampleRows=()=>DEMOS.map((p,i)=>`<div class="sample-row"><span class="product-icon ${['','oats','crackers'][i]}">${['♧','❋','▤'][i]}</span><div class="product-name"><strong>${esc(p.name)}</strong><small>Illustrative example · ${p.quantity}</small></div><span class="tag ${i===1?'green':''}">${['Watch the sugar','Lower sugar','Watch the salt'][i]}</span><button class="row-open" data-demo="${i}" aria-label="Analyse ${esc(p.name)}">↗</button></div>`).join('');
function home(){return `${heading('Know what you’re eating.','Less label confusion. More informed choices.','<span class="date-chip">✦ Your everyday food companion</span>')}<section class="hero"><div class="hero-copy"><div class="eyebrow">A CLOSER LOOK. A BETTER CHOICE.</div><h2>Good food decisions<br>start with <em>clarity.</em></h2><p>Scan a label. Understand the ingredients.<br>Find out what’s really inside your everyday foods.</p><button class="btn primary" data-action="camera">▥ &nbsp; Scan a product &nbsp; ↗</button><span class="reading">Free to explore</span></div><div class="hero-art" aria-hidden="true"><div class="food-jar"><div class="jar-lid"></div><div class="jar-label"><small>THE EVERYDAY PANTRY</small><b>granola</b><span>ALMOND & HONEY</span><i>❧</i></div></div><div class="float-label top"><span class="float-icon">!</span><div><strong>Sugars worth a look</strong><small>Understand the why</small></div></div><div class="float-label bottom"><span class="float-icon">✓</span><div><strong>Every ingredient, clearer</strong><small>Simple, useful explanations</small></div></div><span class="spark">✧</span></div></section><div class="section-label"><h2>Let’s look a little closer</h2><p>Three ways to get started</p></div><section class="action-grid">${[['camera','▥','Scan a barcode','Point your camera at a barcode<br>to look up a product.'],['photo','▧','Upload a food label','A photo of the ingredients.<br>A little more understanding.'],['barcode','⌕','Enter a barcode','Have the number handy?<br>Type it in and take a look.']].map(([a,i,t,p])=>`<button class="action-card" ${a==='camera'?'data-action':'data-tab'}="${a}"><span class="action-icon">${i}</span><span class="card-arrow">↗</span><h3>${t}</h3><p>${p}</p></button>`).join('')}</section><div class="bottom-grid"><section class="panel"><div class="section-label"><h2>A taste of what you’ll discover</h2><span class="pill">Demo labels</span></div>${sampleRows()}</section><section class="panel tip-panel"><div class="eyebrow">A LITTLE LABEL WISDOM <span>✧</span></div><h3>The front tells a story.<br>The back tells you more.</h3><p>“Natural” and “multigrain” don’t tell you everything. Turn the pack around and check the ingredients and nutrition together.</p><button class="text-button" data-view="learn">Learn how we read a label &nbsp; ↗</button><span class="tip-decoration" aria-hidden="true">❋</span></section></div><div class="trust-strip"><span>◎ Clear sources, honest answers</span><span>♧ No account needed</span><span>◉ Listen to your results</span></div>`}
const nutritionFields=[['sugars','Total sugars (g)'],['saturated','Saturated fat (g)'],['salt','Salt (g)'],['fat','Total fat (g)'],['energy','Energy (kcal)'],['protein','Protein (g)'],['fibre','Fibre (g)']];
function manual(){const p=draft||{};return `<h2>Read it from the pack</h2><p>Leave unavailable values blank. Use values per 100 g (or 100 ml for drinks).</p><form id="manual-form"><div class="form-grid"><label class="field full">Product name<input name="name" required maxlength="160" value="${esc(p.name||'')}" placeholder="e.g. Almond & honey granola"></label><label class="field">Brand<input name="brand" maxlength="100" value="${esc(p.brand||'')}" placeholder="Optional"></label><label class="field">Net quantity<input name="quantity" maxlength="50" value="${esc(p.quantity||'')}" placeholder="e.g. 400 g"></label><label class="field">Food type<select name="type"><option value="food">Solid food · per 100 g</option><option value="other" ${p.type==='other'?'selected':''}>Drink / specialised food · unrated</option></select></label><label class="field">Your portion (g or ml)<input name="serving" type="number" min="1" max="2000" step="any" required value="${esc(p.serving||30)}"></label><label class="field full">Ingredient list<textarea name="ingredients" maxlength="12000" placeholder="The full list, in the order shown…">${esc(p.ingredients||'')}</textarea></label><label class="field full">Allergen / “may contain” statement<input name="allergens" maxlength="2000" value="${esc([p.allergens,p.traces].filter(Boolean).join(', '))}" placeholder="e.g. Contains milk. May contain peanuts."></label></div><h3>Nutrition per 100 g / 100 ml</h3><div class="nutrition-inputs">${nutritionFields.map(([k,t])=>`<label class="field">${t}<input name="${k}" type="number" min="0" max="${k==='energy'?1000:100}" step="any" value="${esc(p.nutrition?.[k]??'')}" placeholder="Unknown"></label>`).join('')}</div><p class="hint">Sodium in mg? Salt in g = sodium × 2.5 ÷ 1000. Convert values per serving to per 100 g before entering them.</p><p id="manual-error" class="error" role="alert"></p><button class="btn primary">Understand this product →</button></form>`}
function scan(){return `${heading('A little scan. A lot of clarity.','Start with a barcode, a label photo, or the details on your pack.')}<div class="tabs" role="tablist" aria-label="Input method">${[['barcode','▥ Barcode lookup'],['photo','▧ Label photo'],['manual','⌨ Enter details']].map(([id,t])=>`<button role="tab" aria-selected="${tab===id}" data-tab="${id}" class="${tab===id?'active':''}">${t}</button>`).join('')}</div><div class="scan-layout"><section class="panel">${tab==='barcode'?`<h2>Let’s find your product</h2><p>Scan or enter the digits printed below the barcode.</p><button class="btn soft" data-action="camera">▥ Open barcode camera</button><form id="barcode-form"><label class="field">Barcode number<input name="barcode" inputmode="numeric" autocomplete="off" placeholder="e.g. 3017620422003" required pattern="[0-9 ]{8,20}"></label><p class="hint">EAN / UPC / GTIN · 8, 12, 13 or 14 digits</p><button class="btn primary" id="lookup-btn">Find product →</button><p class="error" role="alert" id="lookup-error"></p></form><div class="notice">Product information comes from Open Food Facts, a community database. Availability and accuracy vary. Always compare with your pack.</div><button class="text-button" data-tab="manual">Can’t find it? Enter the label yourself →</button>`:tab==='photo'?`<h2>Turn a label into plain language</h2><p>Use a clear, close-up photo of the English ingredient list.</p><label class="upload"><span class="action-icon">▧</span><strong>Choose a label photo</strong><small>JPG, PNG or WebP · up to 10 MB</small><input id="label-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="ocr-preview"></div><p id="ocr-status" role="status" class="hint">Recognition runs in your browser. Your photo is not uploaded.</p><div class="notice">Review extracted text before analysis. Add nutrition values manually so a misread number never becomes an automatic judgement.</div><button class="text-button" data-tab="manual">Prefer to type the details? →</button>`:manual()}</section><aside class="panel"><div class="eyebrow">FROM LABEL TO UNDERSTANDING</div><h2>Here’s how it works</h2>${[['Bring your food label','Scan a code, upload a photo, or type what you see.'],['Check the details','Confirm ingredients, food type and values per 100 g. Unknown values stay unknown.'],['Understand your food','Read the reasoning, adjust your portion, or listen to the explanation.']].map(([t,p],i)=>`<div class="step"><span>${i+1}</span><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}<div class="notice green">Preferences stay on this device. <button class="text-button" data-view="profile">Set allergy alerts ↗</button></div><h3>Just exploring?</h3><button class="btn soft" data-demo="0">Try an example label →</button></aside></div>`}
function value(v,unit='g'){const n=number(v);return n===null?'—':`${Number((n*(basis==='portion'?current.serving/100:1)).toFixed(2))} ${unit}`}
function result(){const p=current,a=analyze(p,prefs.allergies);return `<button class="text-button back" data-view="scan">← Scan another product</button><div class="result-header"><span class="product-icon">♧</span><div><div class="eyebrow">${esc(p.brand||'YOUR FOOD LABEL')}</div><h1>${esc(p.name)}</h1><p>${esc(p.quantity||'Net quantity not provided')} · ${esc(p.source)} ${p.demo?' · Not a real product':''}</p></div></div><div class="result-actions"><button class="btn primary" data-action="speak">◉ Listen to explanation</button><button class="btn" data-action="stop">◼ Stop</button><button class="btn" data-action="save">▧ ${saved.some(s=>s.id===p.id)?'Update saved scan':'Save scan'}</button><button class="btn" data-action="edit">✎ Review label</button><button class="btn" data-action="export">↓ Export report</button></div>${a.matches.length?`<div class="notice red"><strong>Allergy alert: ${a.matches.map(esc).join(', ')}.</strong> Matching terms appear in the ingredient, allergen or trace statements. Check the pack; this tool cannot establish safety.</div>`:''}<section class="verdict ${a.unknown.length?'neutral':!a.high.length?'green':''}"><span class="verdict-symbol">${a.unknown.length?'?':a.high.length?'!':'✓'}</span><div><div class="eyebrow">THE LABEL, IN PLAIN LANGUAGE</div><h2>${a.verdict}</h2><p>${a.explanation}</p></div></section><div class="result-grid"><div class="stack"><section class="panel"><div class="section-label"><h2>Nutrition at a glance</h2><select id="basis" class="control" aria-label="Nutrition display basis" style="width:auto;padding:7px;font-size:11px"><option value="100" ${basis==='100'?'selected':''}>Per 100 ${p.type==='food'?'g':'g / ml'}</option><option value="portion" ${basis==='portion'?'selected':''}>Per portion (${p.serving} ${p.type==='food'?'g':'g / ml'})</option></select></div><div class="nutrient-grid">${a.metrics.map(m=>`<div class="nutrient ${m.level}"><small>${m.name}</small><b>${value(m.value)}</b><span class="tag ${m.level==='high'?'red':m.level==='low'?'green':m.level==='unknown'?'neutral':''}">${m.level==='unknown'?'Unrated':m.level}</span><div class="nutrient-line"></div></div>`).join('')}</div><div class="nutrient-extras"><span>Energy <strong>${value(p.nutrition.energy,'kcal')}</strong></span><span>Protein <strong>${value(p.nutrition.protein)}</strong></span><span>Fibre <strong>${value(p.nutrition.fibre)}</strong></span></div><p class="hint">Colours always refer to 100 g of solid food, even when portion amounts are shown. UK label thresholds, not an FSSAI rating.</p><label class="field">Adjust your portion (${p.type==='food'?'g':'g / ml'})<input id="portion" type="number" min="1" max="2000" step="any" value="${p.serving}"></label><details><summary>Why these labels?</summary>${a.metrics.map(m=>`<p class="hint"><strong>${m.name}:</strong> ${m.value===null?'Value missing.':`${m.value} g per 100 g / ml.`} ${p.type==='food'?`Low ≤ ${m.low} g; high > ${m.high} g; values between are moderate.`:'Not rated for this food type.'}</p>`).join('')}<a href="https://www.nhs.uk/live-well/eat-well/food-guidelines-and-food-labels/how-to-read-food-labels/" target="_blank" rel="noopener">NHS: food label thresholds ↗</a></details></section><section class="panel"><div class="section-label"><h2>Let’s unpack the ingredients</h2><span class="pill">${p.ingredients?'Label provided':'Incomplete'}</span></div><p class="ingredients-text">${esc(p.ingredients||'No ingredient list available.')}</p>${a.notes.map(n=>`<div class="ingredient-note"><h3>${n.tone==='amber'?'◌':'◎'} &nbsp; ${n.name}</h3><p>${n.text}</p></div>`).join('')}</section></div><aside class="stack"><section class="panel"><div class="eyebrow">PERSONAL TO YOU</div><h2>Your allergy check</h2><p class="hint">${prefs.allergies.length?`Checking: ${prefs.allergies.map(esc).join(', ')}.`:'No allergy preferences selected.'}</p><div class="notice ${a.matches.length?'red':''}">${a.matches.length?'Matching terms found. Review the full pack.':'No safety clearance: keyword checks can miss allergens, translations and cross-contact.'}</div><p class="hint"><strong>Label statement:</strong> ${esc([p.allergens,p.traces].filter(Boolean).join(' · ')||'Not provided. Check the pack.')}</p><button class="text-button" data-view="profile">Manage allergy preferences ↗</button></section><section class="panel"><div class="eyebrow">BUSINESS VERIFICATION</div><h2>Check the FSSAI licence</h2><span class="tag neutral">Not verified</span><p class="hint" style="margin-top:12px">A barcode identifies a product. The 14-digit FSSAI number identifies a registered or licensed food business.</p><label class="field">FSSAI licence number<input id="fssai" inputmode="numeric" maxlength="14" placeholder="14 digits from your pack"></label><button class="btn soft" data-action="fssai">Open official verification ↗</button><p id="fssai-status" class="hint">Match the business details on the official portal. A licence is not a nutritional endorsement.</p></section><section class="panel"><h2>Know the source</h2><div class="meta-row"><span>Product data</span><strong>${esc(p.source)}</strong></div><div class="meta-row"><span>Rules version</span><strong>${RULE_VERSION}</strong></div><div class="meta-row"><span>Data completeness</span><strong>${a.metrics.filter(m=>m.value!==null).length}/4 key nutrients</strong></div><p class="hint">${p.demo?'This fictional example uses invented values to demonstrate the app.':p.source==='Open Food Facts'?'Community data may be incomplete or outdated. Confirm the exact variant and pack.':'Entered or reviewed by you. Not independently verified by NutriLens.'}</p>${/^https:\/\/world\.openfoodfacts\.org\/product\/\d+$/.test(p.sourceUrl||'')?`<a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener">View original product ↗</a>`:''}</section></aside></div><p class="hint" style="margin-top:20px">Food-label education, not medical advice or a food-safety test. Freshness, contamination, medical needs and overall diet are outside this assessment.</p>`}
function library(){return `${heading('Your label library.','Revisit the foods you’ve explored. Saved only in this browser.',saved.length?'<button class="btn" data-action="clear">Clear library</button>':'')}<section class="panel">${saved.length?saved.map((p,i)=>`<div class="sample-row"><span class="product-icon">♧</span><div class="product-name"><strong>${esc(p.name)}</strong><small>${esc(p.source)} · ${esc(p.quantity||'')}</small></div><button class="btn soft" data-saved="${i}">View report ↗</button><button class="delete-btn" data-delete="${i}" aria-label="Delete ${esc(p.name)}">Remove</button></div>`).join(''):'<div class="empty"><span class="action-icon">▧</span><h2>A little food knowledge, saved.</h2><p>Save a report and it will be here when you need it.</p><button class="btn primary" data-view="scan">Scan your first product →</button></div>'}</section>`}
const compareList=()=>[...saved,...DEMOS.filter(d=>!saved.some(s=>s.id===d.id))];
function compare(){return `${heading('See the difference, side by side.','Compare the same kind of food, using the same amount.')}<section class="panel"><div class="form-grid">${['left','right'].map((s,i)=>`<label class="field">${i?'Compare with':'Choose a food'}<select id="compare-${s}">${compareList().map((p,j)=>`<option value="${j}" ${i===j?'selected':''}>${esc(p.name)}${p.demo?' (demo)':''}</option>`).join('')}</select></label>`).join('')}</div><div id="comparison"></div><p class="hint">Lower numbers do not automatically mean a better food. Compare similar categories and consider ingredients, portions and your needs.</p></section>`}
function compareTable(){const list=compareList(),a=list[+$('#compare-left').value],b=list[+$('#compare-right').value];$('#comparison').innerHTML=`${a.type!==b.type?'<div class="notice">Different food types: these values are not directly comparable.</div>':''}<div class="table-wrap"><table><thead><tr><th>Per 100 g / ml</th><th>${esc(a.name)}</th><th>${esc(b.name)}</th></tr></thead><tbody>${nutritionFields.map(([k,t])=>`<tr><td>${t}</td>${[a,b].map(p=>{const n=number(p.nutrition[k]),level=analyze(p).metrics.find(m=>m.key===k)?.level;return `<td>${n??'Unknown'} ${level&&level!=='unknown'?`<span class="tag ${level==='high'?'red':level==='low'?'green':''}">${level}</span>`:''}</td>`}).join('')}</tr>`).join('')}<tr><td>Data source</td><td>${esc(a.source)}</td><td>${esc(b.source)}</td></tr></tbody></table></div>`}
function profile(){return `${heading('Make it personal.','A few preferences to make your label checks more useful.')}<section class="panel" style="max-width:800px"><h2>Ingredients you need to watch</h2><p class="hint">Highlight matching terms in English ingredient and allergen statements. This limited screen cannot establish that a food is allergen-free.</p><form id="prefs-form"><div class="checkbox-grid">${[['milk','Milk'],['peanuts','Peanuts'],['nuts','Tree nuts'],['gluten','Wheat / gluten'],['soy','Soy'],['eggs','Eggs'],['sesame','Sesame']].map(([v,l])=>`<label class="check-chip"><input name="allergies" type="checkbox" value="${v}" ${prefs.allergies.includes(v)?'checked':''}>${l}</label>`).join('')}</div><button class="btn primary">Save preferences</button></form><div class="notice">Always check the complete pack and “may contain” warnings. No match does not mean safe. Cross-contact may not be captured here.</div><details><summary>Your privacy</summary><p class="hint">Scans and preferences stay in this browser’s local storage. Clearing browser data removes them. Barcode lookups send the code and your IP address to Open Food Facts. OCR downloads its engine from jsDelivr and language assets from the Tesseract project, then reads photos locally. Voice uses your browser or operating system’s speech service; processing depends on device settings. Google Fonts receives normal font requests.</p><button class="btn" data-action="clear-all">Delete saved scans and preferences</button></details></section>`}
function learn(){return `${heading('Clear answers. Clear reasoning.','What we check, where the data comes from, and what we cannot tell you.')}<div class="learn-grid"><section class="panel"><div class="eyebrow">01 / NUTRITION</div><h2>A label guide, with reasons</h2><p>Four nutrients are compared with UK thresholds for solid food. This is an educational screening rule, not an official Nutri-Score, FSSAI rating or complete judgement of healthfulness.</p><table><thead><tr><th>Per 100 g</th><th>Low ≤</th><th>High ></th></tr></thead><tbody>${METRICS.map(m=>`<tr><td>${m.name}</td><td>${m.low} g</td><td>${m.high} g</td></tr>`).join('')}</tbody></table><p class="hint">Values between are moderate. Drinks and specialised foods are not rated. Missing values are never zero. Portion amounts scale, but colours remain based on 100 g.</p><a href="https://www.nhs.uk/live-well/eat-well/food-guidelines-and-food-labels/how-to-read-food-labels/" target="_blank" rel="noopener">NHS: how to read food labels ↗</a></section><section class="panel"><div class="eyebrow">02 / INGREDIENTS</div><h2>Context over scary names</h2><p>A limited dictionary identifies sweeteners, some saturated-fat sources and common additive terms. Presence alone does not tell us dose or individual risk. An unfamiliar name does not make an ingredient toxic.</p><p>English keyword allergy checks may miss synonyms, translations and cross-contact. Always read the pack. This tool does not diagnose conditions or provide clinical recommendations.</p><a href="https://www.food.gov.uk/safety-hygiene/check-the-label" target="_blank" rel="noopener">Food Standards Agency: check the label ↗</a></section><section class="panel"><div class="eyebrow">03 / TRACEABILITY</div><h2>Lookup and verification are different</h2><p>A barcode looks up community-maintained information in Open Food Facts. This is not a direct FSSAI product database connection.</p><p>Use the separate, 14-digit FSSAI licence number on the official portal to check a business. NutriLens does not claim automatic verification or treat a licence as a health endorsement.</p><a href="https://fssai.gov.in/citizen/about-license-verification?dp=Citizen+Services" target="_blank" rel="noopener">FSSAI: official licence verification ↗</a></section><section class="panel"><div class="eyebrow">04 / DATA & LIMITS</div><h2>Honest about the unknowns</h2><p>Community data and OCR can be wrong. Confirm the exact product, food type, ingredient list and nutrition units. All demo products are fictional.</p><p>Open Food Facts data is used under ODbL; individual contents use the Database Contents License. Reports link to their product source. No product photos are copied.</p><p>Rules ${RULE_VERSION} · No hidden AI score · No sponsored recommendations.</p><a href="https://openfoodfacts.github.io/openfoodfacts-server/api/" target="_blank" rel="noopener">Open Food Facts: data and API documentation ↗</a></section></div>`}
function stop(){if('speechSynthesis'in window)speechSynthesis.cancel()}
function render(){stop();$('#saved-count').textContent=saved.length;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===(view==='result'?'scan':view)));$('#breadcrumb').textContent={home:'Your food companion',scan:'Explore a food label',result:'Your food, explained',saved:'Your saved scans',compare:'Compare foods',learn:'Behind the analysis',profile:'Your preferences'}[view];main.innerHTML=({home,scan,result,saved:library,compare,learn,profile}[view]||home)();if(view==='compare')compareTable()}
function go(v){view=v;render();window.scrollTo(0,0);main.focus({preventScroll:true})}
function show(p){current=structuredClone(p);basis='100';go('result')}
function err(id,s){const el=$(id);if(el)el.textContent=s;else toast(s)}
async function lookup(raw){const code=raw.replace(/\s/g,'');if(!validBarcode(code)){err('#lookup-error','Enter a valid 8, 12, 13 or 14-digit barcode, including the check digit.');return}if(cache.has(code)){show(cache.get(code));return}if(busy)return;if(Date.now()-lastLookup<5000){toast('Wait a few seconds before another lookup.');return}busy=true;lastLookup=Date.now();const btn=$('#lookup-btn');if(btn){btn.disabled=true;btn.innerHTML='<span class="loading"></span> Finding your product…'}err('#lookup-error','');try{const fields='product_name,product_name_en,brands,quantity,ingredients_text,ingredients_text_en,allergens_tags,traces_tags,categories_tags,nutriments';const r=await fetch(`https://world.openfoodfacts.org/api/v3/product/${code}?fields=${fields}`,{signal:AbortSignal.timeout(15000)});if(r.status===404)throw Error('Product not found. Use a label photo or enter the details.');if(r.status===429)throw Error('The database is busy. Wait a minute before trying again.');if(!r.ok)throw Error('The database is unavailable. You can still enter a label manually.');const data=await r.json();if(!data.product)throw Error('No product found. Enter the details on the pack.');const p=fromOFF(data.product,code);cache.set(code,p);show(p);toast('Confirm the food type and label details before relying on this report.')}catch(e){err('#lookup-error',e.name==='TimeoutError'?'Lookup timed out. Try again or enter the label manually.':e instanceof TypeError?'Couldn’t connect. Check your connection or enter the label manually.':e.message)}finally{busy=false;if(btn?.isConnected){btn.disabled=false;btn.textContent='Find product →'}}}
function stopCamera(){clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());stream=null}
async function camera(){tab='barcode';go('scan');if(!('BarcodeDetector'in window)){toast('Camera scanning is unavailable in this browser. Enter the barcode below.');$('#barcode-form input').focus();return}if(!navigator.mediaDevices?.getUserMedia){toast('Camera requires HTTPS or localhost. Enter the barcode below.');return}modal.innerHTML='<div class="inline"><h2>Find the barcode</h2><button class="btn" data-action="close-modal">Close ✕</button></div><p>Hold the code steady in good light.</p><video id="camera" autoplay playsinline muted></video><p id="camera-status" role="status">Starting camera…</p>';modal.showModal();try{const formats=(await BarcodeDetector.getSupportedFormats()).filter(f=>['ean_13','ean_8','upc_a','upc_e','itf'].includes(f));if(!formats.length)throw Error();const detector=new BarcodeDetector({formats});const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(!modal.open){media.getTracks().forEach(t=>t.stop());return}stream=media;const v=$('#camera');v.srcObject=stream;await v.play();$('#camera-status').textContent='Keep the code within the camera view.';const tick=async()=>{if(!stream||!modal.open)return;try{const codes=await detector.detect(v),found=codes.find(c=>validBarcode(c.rawValue));if(found){stopCamera();modal.close();lookup(found.rawValue);return}}catch{}timer=setTimeout(tick,300)};tick()}catch{stopCamera();modal.close();toast('Camera could not start. Check permission or type the barcode.')}}
let ocrPromise;function loadOCR(){if(window.Tesseract)return Promise.resolve(window.Tesseract);if(ocrPromise)return ocrPromise;ocrPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';s.onload=()=>resolve(window.Tesseract);s.onerror=()=>{ocrPromise=null;s.remove();reject(Error('Could not load text recognition. Check your connection or type the label.'))};document.head.appendChild(s)});return ocrPromise}
async function photo(file){if(!file||ocrBusy)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10485760){toast('Choose a JPG, PNG or WebP smaller than 10 MB.');return}ocrBusy=true;const status=$('#ocr-status'),input=$('#label-photo');input.disabled=true;let worker,url;try{url=URL.createObjectURL(file);const img=new Image();img.src=url;img.alt='Your uploaded label';img.className='preview-image';$('#ocr-preview').replaceChildren(img);status.textContent='Loading local text recognition…';const T=await loadOCR();worker=await T.createWorker('eng',1,{logger:m=>{if(status.isConnected)status.textContent=m.status+' '+(m.progress?Math.round(m.progress*100)+'%':'')}});const {data}=await worker.recognize(file);if(!data.text.trim())throw Error('No readable text found. Try a sharper photo or type the label.');draft={ingredients:data.text.trim()};tab='manual';go('scan');toast('Review the words, keep only ingredients in the list, and add nutrition values.')}catch(e){if(status.isConnected)status.textContent=e.message;else toast(e.message)}finally{await worker?.terminate();if(url)URL.revokeObjectURL(url);ocrBusy=false;if(input.isConnected)input.disabled=false}}
function speak(){if(!('speechSynthesis'in window)){toast('Voice is unavailable in this browser. Read the full explanation on screen.');return}stop();const a=analyze(current,prefs.allergies);const text=`${current.name}. ${current.demo?'Fictional demonstration product. ':''}${a.verdict}. ${a.explanation} ${a.metrics.map(m=>`${m.name}: ${m.value===null?'not available':m.value+' grams per 100 grams, '+m.level}.`).join(' ')} ${a.matches.length?'Allergy alert: '+a.matches.join(', ')+'. ':''}${a.notes.map(n=>n.name+'. '+n.text).join(' ')} Educational screening only. The FSSAI licence has not been verified.`;const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.93;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('Voice playback failed. Try a different browser or installed voice.')};speechSynthesis.speak(u);toast('Reading the report. Use Stop to end playback.')}
const actions={camera,speak,stop,'close-modal':()=>{stopCamera();modal.close()},save:()=>{current.date=new Date().toISOString();saved=[structuredClone(current),...saved.filter(p=>p.id!==current.id)].slice(0,50);const ok=persist('nl-scans',saved);render();if(ok)toast('Saved to your label library on this device.')},edit:()=>{draft=structuredClone(current);tab='manual';go('scan')},export:()=>{const blob=new Blob([JSON.stringify({product:current,assessment:analyze(current,prefs.allergies),rulesVersion:RULE_VERSION,fssai:'Not verified',disclaimer:'Educational screening, not a medical or food-safety assessment.'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nutrilens-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},fssai:()=>{const code=$('#fssai').value.trim();if(!/^\d{14}$/.test(code)){err('#fssai-status','Enter the 14-digit FSSAI licence number, which is different from the barcode.');return}window.open('https://fssai.gov.in/citizen/about-license-verification?dp=Citizen+Services','_blank','noopener');$('#fssai-status').textContent=`Use ${code} on the official portal. Match the business name, address and status. NutriLens has not verified it.`},clear:()=>{if(confirm('Delete all saved scans from this browser?')){saved=[];persist('nl-scans',saved);render()}},'clear-all':()=>{if(confirm('Delete all saved scans and preferences?')){saved=[];prefs={allergies:[]};persist('nl-scans',saved);persist('nl-prefs',prefs);render();toast('Saved scans and preferences cleared.')}}};
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b)return;if(b.matches('a.brand')){e.preventDefault();go('home')}else if(b.dataset.view)go(b.dataset.view);else if(b.dataset.tab){tab=b.dataset.tab;go('scan')}else if(b.dataset.demo!==undefined)show(DEMOS[+b.dataset.demo]);else if(b.dataset.saved!==undefined)show(saved[+b.dataset.saved]);else if(b.dataset.delete!==undefined){saved.splice(+b.dataset.delete,1);persist('nl-scans',saved);render()}else if(b.dataset.action)actions[b.dataset.action]?.()});
document.addEventListener('submit',e=>{if(e.target.id==='barcode-form'){e.preventDefault();lookup(new FormData(e.target).get('barcode'))}if(e.target.id==='prefs-form'){e.preventDefault();prefs.allergies=new FormData(e.target).getAll('allergies');if(persist('nl-prefs',prefs))toast('Preferences saved.')}if(e.target.id==='manual-form'){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim()){err('#manual-error','Enter a product name.');return}const nutrition=Object.fromEntries(nutritionFields.map(([k])=>[k,number(f[k])]));if(nutrition.saturated!==null&&nutrition.fat!==null&&nutrition.saturated>nutrition.fat){err('#manual-error','Saturated fat cannot exceed total fat. Check the values and units.');return}const p={id:draft?.id&&!draft.demo?draft.id:crypto.randomUUID(),name:f.name.trim(),brand:f.brand.trim(),quantity:f.quantity.trim(),ingredients:f.ingredients.trim(),allergens:f.allergens.trim(),type:f.type,serving:Number(f.serving),nutrition,source:'Reviewed label',date:new Date().toISOString()};draft=null;show(p)}});
document.addEventListener('change',e=>{if(e.target.id==='label-photo')photo(e.target.files[0]);if(e.target.id==='basis'){basis=e.target.value;render()}if(e.target.id==='portion'){const n=Number(e.target.value);if(!Number.isFinite(n)||n<1||n>2000){toast('Choose a portion from 1 to 2,000 g / ml.');e.target.value=current.serving;return}current.serving=n;basis='portion';render()}if(e.target.id.startsWith('compare-'))compareTable()});modal.addEventListener('close',stopCamera);modal.addEventListener('cancel',stopCamera);window.addEventListener('pagehide',()=>{stopCamera();stop()});render();
